INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES
('81', 'As ocorrências arqueológicas que forem reconhecidas durante o acompanhamento arqueológico da obra devem, tanto quanto possível, e em função do seu valor patrimonial, ser conservadas in situ (mesmo que de forma passiva), de tal forma que não se degrade o seu estado de conservação atual. Os achados móveis devem ser colocados em depósito credenciado pelo organismo de tutela do património cultural. Contudo, perante o elevado potencial arqueológico de toda a área alvo de afetação do projeto, a eventual necessidade de exumação de espólio arqueológico, onde algum desse espólio pode ser sujeito a um acelerado processo de decomposição, implica a criação de uma ou mais reservas submersas primárias e transitórias até a sua entrega a Tutela do Património, para depositar esses bens móveis, protegendo-os assim da degradação irreversível a que ficarão sujeitos se permanecerem em contacto direto com o ambiente atmosférico durante a fase de execução. Desta forma, na equipa deve ter um elemento de conservação e restauro, especializado na área do tratamento e conservação de espólio resultante de meio submerso.', 'EE | RAP', 10, 121),
('82', 'Garantir a salvaguarda pelo registo arqueológico da totalidade dos vestígios e contextos a afetar diretamente pela obra, independentemente do seu meio. No caso de elementos arquitetónicos, através de registo gráfico, fotográfico e da elaboração de memória descritiva; no caso de sítios arqueológicos, através da sua escavação integral. Complementarmente podem ser necessários trabalhos de conservação e restauro.', 'EE | RAP', 10, 122),
('83', 'Proceder a uma caracterização e avaliação regular dos bens e contextos arqueológicos identificados, bem como em alguns locais aleatórios da área dragada numa área minimamente representativa. Este trabalho pode implicar a prospeção arqueológica visual e por mergulho com escafandro autónomo.', 'EE | RAP', 10, 123),
('84', 'Proceder, em caso de identificação de bens isolados e das estruturas náuticas, a datações radiométricas {do tipo wiggle-match}, análises estruturais, dendrocronológicas, caracterização e identificação da madeira, entre outras, nomeadamente sobre elementos cujos contextos arqueológicos não permitam atribuir uma cronologia clara. Deve-se ainda assegurar a recolha de amostras de madeira para outras análises.', 'EE | RAP', 10, 124),
('85', 'Assegurar a conservação preventiva para os bens e as estruturas arqueológicas alvo de trabalhos arqueológicos, evitando a degradação irreversível a que ficarão sujeitos durante a fase de execução. A exumação de espólio arqueológico, implica a criação de uma ou mais reservas primárias e transitórias, a definição das metodologias de transporte, acondicionamento, registo e inventariação.', 'EE | RAP', 10, 125),
('86', 'Os achados móveis colhidos no decurso da obra devem ser colocados em depósito credenciado pelo organismo de tutela do património cultural.', 'EE | RAP', 10, 126),
('87', 'Proceder à desativação da área afeta aos trabalhos para a execução da obra, com a desmontagem dos estaleiros e remoção de todos os equipamentos, maquinaria de apoio, depósitos de materiais, entre outros. Proceder à limpeza destes locais, no mínimo com a reposição das condições existentes antes do início dos trabalhos.', 'EE', 12, 127),
('88', 'Assegurar a reposição e/ou substituição de eventuais infraestruturas, equipamentos e/ou serviços existentes nas zonas em obra e áreas adjacentes, que sejam eventualmente afetadas no decurso da obra.', 'EE', 12, 128),
('89', 'Proceder à reparação do pavimento eventualmente danificado nas estradas utilizadas nos percursos de acesso ao Data Center pela circulação de veículos pesados durante a construção.', 'EE', 12, 129),
('90', 'Proceder à recuperação de caminhos e vias utilizados como acesso aos locais de instalação dos apoios das Linhas elétricas e desativar os acessos abertos e que não tenham utilidade posterior. A recuperação inclui operações de limpeza e remoção de todos os materiais, de remoção completa de pavimentos existentes, de descompactação do solo, regularização/modelação do terreno, de forma tão naturalizada quanto possível e o seu revestimento com as terras vegetais, de forma a criar condições favoráveis à regeneração natural e crescimento da vegetação autóctone.', 'EE', 12, 130),
('91', 'Proceder à recuperação paisagística dos locais de empréstimo de terras, caso se constate a necessidade de recurso a materiais provenientes do exterior da área de intervenção.', 'EE', 12, 131),
('92', 'Assegurar o adequado funcionamento do sistema de arrefecimento térmico (captação e rejeição de água do mar) e da utilização das infraestruturas costeiras de proteção associadas, em articulação com a respetiva entidade gestora.', 'DO', 12, 132),
('93', 'Realizar auditorias energéticas com vista a identificação de melhorias ao nível da redução do consumo de energia, como a otimização de equipamentos, utilização de iluminação mais eficiente e a implementação de sistemas de monitorização e controlo avançados.', 'DO | EE', 12, 133),
('94', 'Definir e implementar um plano de inspeção de fugas dos equipamentos, de acordo com a legislação em vigor, atendendo a eventual utilização de gases fluorados nos equipamentos inerentes ao projeto em causa.', 'DO | EE', 12, 134),
('95', 'Deve ser assegurada pela entidade responsável pela exploração das linhas elétricas, a gestão do combustível numa faixa envolvente a projeção vertical dos cabos condutores exteriores, no âmbito do Sistema de Gestão Integrada de Fogos Rurais.', 'DO | EE', 12, 135),
('96', 'A desmatação e controlo da vegetação nos corredores das linhas elétricas deve ser efetuado sem recurso a herbicidas, devendo ser realizado por meios mecânicos, preferencialmente sem remexer o solo.', 'DO | EE', 12, 136),
('97', 'Assegurar a limpeza do material combustível na envolvente do Data Center, bem como nas respetivas vias de acesso, de modo a garantir a existência de uma faixa de segurança contra incêndios, no âmbito do Sistema de Gestão Integrada de Fogos Rurais.', 'DO | EE', 12, 137),
('98', 'Na aquisição de serviços (manutenção, fornecimento de materiais, fornecimento de bens e serviços) e contratação de mão-de-obra, privilegiar, sempre que possível, empresas da região, desta forma fomentando o emprego permanente e indireto originado pela exploração do Data Center.', 'DO', 12, 138),
('99', 'Garantir a aquisição de equipamentos com maior eficiência energética e hídrica.', 'DO', 12, 139),
('100', 'Proceder à manutenção e revisão periódica dos equipamentos, de forma a manter as normais condições de funcionamento e assegurar a minimização em termos de emissões de ruído e, ainda, para reduzir, na fonte, a poluição do ar.', 'DO | EE', 12, 140);